from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # Normalize so a < b
        pairs = []
        for x, y in conflictingPairs:
            if x > y:
                x, y = y, x
            pairs.append((x, y))

        m = len(pairs)
        # Group by b
        by_b = [[] for _ in range(n + 2)]
        for i, (a, b) in enumerate(pairs):
            by_b[b].append((a, i))

        savings = [0] * m
        total_bad = 0

        max1_a = 0
        max1_id = -1
        max2_a = 0

        for r in range(1, n + 1):
            for a, i in by_b[r]:
                if a > max1_a:
                    max2_a = max1_a
                    max1_a = a
                    max1_id = i
                elif a > max2_a:
                    max2_a = a

            total_bad += max1_a
            if max1_id != -1:
                savings[max1_id] += max1_a - max2_a

        total_subarrays = n * (n + 1) // 2
        max_savings = max(savings) if savings else 0
        return total_subarrays - total_bad + max_savings

